_POLICY_TEXT = ("本模块不授予模型训练或公司长期归档权限。60 天是内测保存上限，不是法定期限；应以实际授权覆盖的用途、范围和更短期限为准。"
                "撤回、到期或删除会阻止访问并请求清理，不代表已删除校方下载副本或所有备份。本平台不作诊断，也不宣称已完成法律合规认证。")


def _shell(content: str, *, admin: bool = False, account: Any | None = None, active: str = "students") -> str:
    back = "/demo2/admin" if admin else "/demo2/students"
    label = "返回公司后台" if admin else "返回本校名册"
    actions = (f'<a class="button quiet" id="backLink" href="{back}">{label}</a>'
               '<button class="button" id="refreshButton" type="button">刷新记录</button>')
    header = (admin_header("dossiers", account, logout_bound=False, extra_actions=actions, page="admin_dossiers")
              if admin else
              teacher_header(active, account, logout_bound=False, extra_actions=actions, page=f"dossier:{active}"))
    return f"""{header}
<main class="page-shell" id="mainContent"><div class="page-message" id="pageMessage" role="alert" tabindex="-1"></div>{content}<div class="policy-note"><details class="rx-disclosure" id="policyNote"><summary><span>使用边界与免责声明</span></summary><div class="rx-disclosure-body"><p>{_POLICY_TEXT}</p></div></details></div></main>"""


