COMMON = r"""
const ACCOUNT=__ACCOUNT__,API='/api/v1/demo2/dossier',byId=id=>document.getElementById(id);
const teacher=ACCOUNT.role==='school_uploader',admin=ACCOUNT.role==='company_admin';
let workspace=null,loading=false,writing=false,uncertain=false,dirty=false;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types={iep:'个别化教育计划（IEP）',professional_assessment:'专业评估',five_domain:'五领域评估',safety_support:'安全与支持资料'};
const labels={learning_goals:'学习目标',support_methods:'支持方法',safety_notes:'安全注意事项',professional_conclusion:'专业结论（仅录入已获授权的原文或摘要）'};
const statusName=value=>({active:'有效',available:'可用',expired:'已过期',withdrawn:'已撤回',revoked:'已撤回',deleted:'已删除',deletion_pending:'不可访问 · 待物理清理',superseded:'历史版本',confirmed:'已确认',outdated:'身份依据已过期',unavailable:'不可用'}[value]||'请核对当前记录');
const dateString=value=>[value.getFullYear(),String(value.getMonth()+1).padStart(2,'0'),String(value.getDate()).padStart(2,'0')].join('-');
const today=()=>dateString(new Date()),future=days=>{const value=new Date();value.setDate(value.getDate()+days);return dateString(value);};
const usableDocument=doc=>doc.available===true&&typeof doc.retain_until==='string'&&doc.retain_until>today();
const expiryNotice=doc=>usableDocument(doc)&&Date.parse(doc.retain_until+'T00:00:00Z')-Date.parse(today()+'T00:00:00Z')<=15*86400000?'<p class="expiry-note">即将到期：'+esc(doc.retain_until)+'。到期后摘要与原件不可访问；这是站内提醒，不会发送短信。</p>':'';
const daysUntil=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)?Math.round((Date.parse(value+'T00:00:00Z')-Date.parse(today()+'T00:00:00Z'))/86400000):NaN;
const countdown=(value,soonDays=15)=>{const days=daysUntil(value);if(!Number.isFinite(days)||days<=0)return '';return '<span class="countdown'+(days<=soonDays?' soon':'')+'" title="'+esc(value)+' 零点起不可访问">还有 '+days+' 天到期</span>';};
const TYPE_ICONS=__TYPE_ICONS__;
const typeIcon=type=>'<span class="doc-icon" data-type="'+esc(type)+'" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+(TYPE_ICONS[type]||TYPE_ICONS.default)+'</svg></span>';
const shortId=value=>window.RxUI?RxUI.shortId(value):String(value||'').slice(0,8);
const idChip=(value,label)=>window.RxUI?RxUI.shortIdHtml(value,label):'<code title="'+esc(value)+'">'+esc(String(value||'').slice(0,8)||'未返回')+'</code>';
const badge=(text,tone)=>'<span class="rx-badge rx-badge-'+tone+'">'+esc(text)+'</span>';
function docState(doc,usable){if(usable)return ['可用','success'];if(['withdrawn','revoked'].includes(doc.status))return ['已撤回','neutral'];if(doc.status==='expired'||(doc.retain_until&&doc.retain_until<=today()))return ['已过期','warning'];if(['deleted','deletion_pending'].includes(doc.status))return [statusName(doc.status),'neutral'];if(doc.status==='superseded')return ['历史版本','neutral'];if(doc.available===true)return ['授权不可用','warning'];return [statusName(doc.status),'neutral'];}
function toast(text,tone='success'){if(window.RxUI)RxUI.toast(text,tone,3200);}
// Irreversible actions use the shared dialog (title, consequences, red button); window.confirm is only the no-kit fallback.
function confirmDanger(opts){if(window.RxUI?.confirmDialog)return RxUI.confirmDialog(opts);return Promise.resolve(window.confirm(opts.title+'\n'+opts.message+' '+(opts.consequences||[]).join(' ')));}
const codeSuffix=(status,code)=>window.RxUI?.describeError?'（错误码：'+RxUI.describeError(status,code).label+'）':'';
function notice(text,kind=''){const node=byId('pageMessage');node.textContent=text;node.className='page-message visible '+kind;node.focus();}
function clearNotice(){byId('pageMessage').textContent='';byId('pageMessage').className='page-message';}
function queryId(key){const params=new URLSearchParams(location.search),values=params.getAll(key);return values.length===1&&/^[A-Za-z0-9_-]{1,128}$/.test(values[0])?values[0]:'';}
async function request(path,payload,download=false){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);
  try{const response=await fetch(API+path,{credentials:'same-origin',cache:'no-store',signal:controller.signal,...(payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})});
    if(response.status===401){workspace=null;uncertain=true;clearContent();try{sessionStorage.setItem('demo2_notice','登录已过期，请重新登录后返回资料页。');}catch(_){}location.assign('/demo2/login');}
    if(download&&response.ok){return await response.blob();}
    const data=await response.json().catch(()=>null);
    if(!response.ok||!data||data.error){const error=new Error(response.status===403?'当前账号无权查看或操作这些资料，请返回自己的学校名册。':data?.error?.message||({401:'登录已过期，请重新登录。',404:'资料不存在或已不可用，请刷新记录。',409:'记录或身份依据已变化，请刷新后核对。',410:'资料已到期或撤回，请刷新记录。',503:'加密存储暂不可用，请稍后刷新；不会改为明文保存。'}[response.status])||'未取得有效响应，请刷新记录核对。');error.message+=codeSuffix(response.status,data?.error?.code);error.status=response.status;error.code=data?.error?.code;error.field=data?.error?.field;throw error;}return data;
  }catch(error){if(error.name==='AbortError')throw new Error('请求超时，结果尚未确认。请刷新记录后再操作。');if(error instanceof TypeError)throw new Error('网络连接失败，结果尚未确认。请检查网络并刷新记录。');throw error;}finally{clearTimeout(timer);}
}
async function download(path,name){if(writing||loading||uncertain)return;try{const blob=await request(path,undefined,true),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已开始下载：'+name);}catch(error){uncertain=true;workspace=null;clearContent();controls();notice(error.message+' 请刷新记录确认可用性。');}}
async function mutate(path,payload,resultKey,verify,success){
  if(writing||loading||uncertain)return;writing=true;clearNotice();controls();
  try{const result=await request(path,payload);if(!result[resultKey])throw new Error('提交结果尚未确认，请刷新记录，避免重复提交。');dirty=false;resetInputs();const ok=await load(true);if(!ok||!verify(result,workspace))throw new Error('请求已提交，但刷新结果尚未确认这次变更。请刷新核对，暂勿重复提交。');const text=success?.text||'变更已保存';notice(text+'。已重新读取服务器记录，变更已确认。','success');toast(text);success?.after?.(result);}
  catch(error){uncertain=true;workspace=null;clearContent();notice(error.message+' 当前已暂停写入，请先刷新核对。');}
  finally{writing=false;controls();}
}
function flash(selector){const node=document.querySelector(selector);if(!node)return;node.classList.add('is-new');node.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});setTimeout(()=>node.classList.remove('is-new'),5000);}
const sourceReason={available:'有效依据',reference_withdrawn:'本课引用授权已撤回',authorization_withdrawn:'授权已撤回',authorization_expired:'授权已到期',authorization_missing:'授权缺失',document_deleted:'版本已删除',document_withdrawn:'授权已撤回',document_expired:'保存期限已到期',document_missing:'版本不存在',document_unavailable:'版本不可用',outdated_revision:'身份版本已变化',identity_unavailable:'身份确认已失效',task_unavailable:'任务证据不可用'};
function referenceRows(items,options={}){return items.length?items.map(ref=>{const current=ref.evidence_status==='current',available=ref.available===true,withdrawn=ref.withdrawn===true||ref.status==='withdrawn';const evidence={current:'当前身份依据有效',outdated_revision:'身份版本已变化',identity_unavailable:'身份确认已失效',task_unavailable:'任务证据不可用'}[ref.evidence_status]||'身份依据未确认';const sources=Array.isArray(ref.sources)&&ref.sources.length?ref.sources:(ref.document_versions||[]).map(doc=>({...doc,valid_as_evidence:available,reason:available?'available':''}));const sourcesOk=ref.sources_available===undefined?available:ref.sources_available===true;const created=window.RxUI&&ref.created_at?RxUI.formatTime(ref.created_at):(ref.created_at||'时间未返回');return `<article class="record" data-reference-card="${esc(ref.reference_id||'')}"><div class="record-head"><h3>课堂引用记录</h3><span class="doc-badges">${withdrawn?badge('本课授权已撤回','neutral'):!available?badge('已失效','warning'):badge('有效','success')}</span></div><p>引用编号 ${idChip(ref.reference_id,'引用编号')} · ${esc(created)}</p><p>${esc(evidence)} · ${sourcesOk?'资料来源当前可用':'资料来源已不可用'}</p><p>引用版本：${sources.map(doc=>esc(types[doc.document_type]||'资料')+' '+idChip(doc.document_id,'资料编号')+' / 版本 '+esc(doc.version)+(doc.valid_as_evidence===true?'':' <span class="status unavailable">失效 · '+esc(sourceReason[doc.reason]||'不可作为有效依据')+'</span>')).join('；')||'未返回'}</p><p>历史引用不会自动切换到新资料版本。下载时会重新核验资料与身份依据，失效来源会被标记。</p>${withdrawn?'<p class="gate">本课引用授权已于 '+esc(ref.withdrawn_at||'')+' 撤回，IEP 与专业资料不再进入本课分析和评分。</p>':!current||!available?'<p class="gate">存在不可用或未确认依据，不应视为有效学生归属或有效资料引用。</p>':''}${ref.reference_id?`<div class="record-actions"><button class="button" type="button" data-reference="${esc(ref.reference_id)}">下载课堂引用记录</button>${options.withdraw&&!withdrawn?`<button class="button danger" type="button" data-withdraw-reference="${esc(ref.reference_id)}">撤回本课引用授权</button>`:''}</div>`:''}</article>`;}).join(''):'<div class="empty-state">尚无课堂引用记录。请从已确认学生的视频任务进入“关联学生资料”。</div>';}
document.addEventListener('click',event=>{const button=event.target.closest('[data-reference]');if(button)download('/reference?reference_id='+encodeURIComponent(button.dataset.reference),'课堂引用记录_'+shortId(button.dataset.reference)+'.json');});
document.addEventListener('input',event=>{if(event.target.closest('form'))dirty=true;});
document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(link&&(dirty||writing)&&!window.confirm('当前内容尚未保存或请求未完成，仍要离开吗？'))event.preventDefault();});
if(window.RxUI&&window.RxUI.navGuard)window.RxUI.navGuard(()=>dirty||writing);
window.addEventListener('beforeunload',event=>{if((dirty||writing)&&!(window.RxUI&&window.RxUI.isLeaving&&window.RxUI.isLeaving())){event.preventDefault();event.returnValue='';}});
byId('refreshButton').addEventListener('click',()=>{if(!writing&&(!dirty||window.confirm('刷新会放弃未保存内容，继续吗？'))){dirty=false;resetInputs();load();}});
""".replace("__TYPE_ICONS__", _TYPE_ICON_JSON)


def render_student(account: Any | None = None) -> str:
    summaries = "".join(
        f'<div class="field"><label for="{key}">{label}</label><textarea id="{key}" maxlength="2000" autocomplete="off"></textarea><small>最多 2000 字；不使用模型补写。</small></div>'
        for key, label in (("learning_goals", "学习目标"), ("support_methods", "支持方法"), ("safety_notes", "安全注意事项"), ("professional_conclusion", "专业结论（仅录入已获授权的信息）"))
    )
    content = """<div class="page-heading"><div><span class="eyebrow">本校学生 · 受限资料</span><h1>学生资料与授权</h1><p class="lead">先核对学生，再登记授权；每份资料独立保留版本和截止日期。</p></div></div>
<section class="scope-strip student-card" aria-labelledby="studentName"><div class="student-card-head"><span class="rx-avatar rx-avatar-lg" id="studentAvatar" aria-hidden="true">?</span><div class="student-card-main"><strong id="studentName">正在核对学生</strong><p id="studentMeta" class="student-badges"></p></div></div><label class="check"><input id="studentVerified" type="checkbox" disabled><span>已核对姓名、校内编号和班级，资料确属这位学生。</span></label></section>
<section class="reminder-card" id="reminderCard" aria-labelledby="reminderTitle"><h2 id="reminderTitle">__ALERT__使用提醒</h2><ul><li id="workspaceGate" role="status">正在读取本账号、本校学生资料。</li><li>授权勾选只是校方登记声明，不等同于法律同意证明；权限和期限以服务器核验为准。</li><li>资料只用于本校教育支持，系统不作诊断，也不会自动生成专业结论。</li></ul><details><summary>查看完整说明</summary><ul><li id="legacyNotice">旧资料库不会按姓名自动迁移。请核对正确学生与授权后重新录入。</li><li>写入的授权依据、摘要与原件由服务端加密保存；加密存储不可用时不会回退为明文保存。</li><li>每次更新都会新建版本，不覆盖旧版本或历史课堂引用；过期、撤回与删除的记录不再展示原内容。</li><li>撤回授权会让相关摘要和原件立即不可访问并请求清理，引用这些资料的课堂报告会被标记为已过期。</li></ul></details></section>
<div class="dossier-tabs rx-tabs" role="tablist" aria-label="学生资料分区"><button class="rx-tab" id="tabDocuments" type="button" role="tab" aria-selected="false" aria-controls="panelDocuments" tabindex="-1">资料与版本<span class="rx-tab-count" id="countDocuments" aria-label="资料版本数量">–</span></button><button class="rx-tab" id="tabAuthorization" type="button" role="tab" aria-selected="true" aria-controls="panelAuthorization">授权与期限<span class="rx-tab-count" id="countAuthorization" aria-label="有效授权数量">–</span></button><button class="rx-tab" id="tabReferences" type="button" role="tab" aria-selected="false" aria-controls="panelReferences" tabindex="-1">课堂引用<span class="rx-tab-count" id="countReferences" aria-label="课堂引用数量">–</span></button></div>
<section id="panelAuthorization" role="tabpanel" aria-labelledby="tabAuthorization"><div class="dossier-grid"><div><h2>当前授权</h2><p class="help">用途固定为教育支持；不会授予训练权限或公司长期归档权限。</p><div id="authorizationRecord" class="records"></div></div><div class="entry-pane"><h2>登记资料授权</h2><p class="help">登记声明不替代实际授权证明。请核对校方获得的授权覆盖本次学生、资料范围、用途和期限。</p><form id="authorizationForm" class="dossier-form"><fieldset id="authorizationFields" disabled><div class="field"><label for="authorizationReference">授权依据（必填）</label><textarea id="authorizationReference" required maxlength="500" placeholder="填写授权记录编号、签署日期和校内保管部门，不抄录多余敏感信息。"></textarea></div><div class="field"><label for="storageMode">获准保存的范围（必选）</label><select id="storageMode" required><option value="">请选择授权覆盖范围</option><option value="summary_only">仅保存教师录入的授权摘要，不上传原件</option><option value="original_and_summary">允许保存摘要及可选原件</option></select></div><div class="field"><label for="authorizationUntil">授权有效期至（必填）</label><input id="authorizationUntil" type="date" required></div><p class="date-help">按实际授权填写，内测最多 60 天。<strong>所选日期零点起不可访问</strong>（服务器本地时间，当前内测为 Asia/Shanghai 北京时间）。</p><label class="check"><input id="authorizationConfirmed" type="checkbox" required><span>已核实本学生资料的实际授权，覆盖教育支持用途、上述保存范围和期限。</span></label><button class="button primary" id="saveAuthorization" type="submit">登记授权</button></fieldset><p class="help" id="authorizationHelp" role="status">请先核对学生。</p></form></div></div></section>
<section id="panelDocuments" role="tabpanel" aria-labelledby="tabDocuments" hidden><div class="dossier-grid"><div><h2>资料与版本</h2><p class="help">每次更新新建一个版本，不覆盖旧版本或历史课堂引用。</p><p class="iep-status" id="iepStatus" role="status" hidden></p><div id="documentList" class="records"></div></div><div class="entry-pane"><h2 id="documentFormTitle">新增资料</h2><p class="scope-hint" id="documentGate">先登记有效授权。</p><form id="documentForm" novalidate class="dossier-form"><fieldset id="documentFields" disabled><input id="supersedesId" type="hidden" value="">
<section class="form-section" aria-labelledby="sectionBasic"><h3 class="form-section-title" id="sectionBasic"><b>1</b>基本信息</h3><div class="form-pair"><div class="field"><label for="documentType">资料类型（必选）</label><select id="documentType" required><option value="">请选择资料类型</option><option value="iep">个别化教育计划（IEP）</option><option value="professional_assessment">专业评估</option><option value="five_domain">五领域评估</option><option value="safety_support">安全与支持资料</option></select></div><div class="field"><label for="documentDate">资料日期（必填）</label><input id="documentDate" type="date" required></div></div><div class="field"><label for="sourceRef">资料来源（必填）</label><input id="sourceRef" required maxlength="200" placeholder="来源机构、记录编号或校内资料出处"><small id="sourceRefCount">最多 200 字</small></div></section>
<section class="form-section" aria-labelledby="sectionRetention"><h3 class="form-section-title" id="sectionRetention"><b>2</b>保存与期限</h3><div class="field"><label for="retainUntil">资料保存至（必填）</label><input id="retainUntil" type="date" required><small class="field-error" id="retainUntilError" role="alert" hidden></small></div><p class="date-help" id="retainHelp">不得晚于授权截止日期；<strong>所选日期零点起不可访问</strong>（服务器本地时间，当前内测为北京时间）。</p></section>
<section class="form-section" aria-labelledby="sectionContent"><h3 class="form-section-title" id="sectionContent"><b>3</b>内容</h3><div id="dossierIepIntakeWrap" hidden><div id="dossierIepIntake"></div><p class="help" id="dossierIepIntakeHint">上传 IEP 文件并确认摘要（或填写人工补充）后，保存时将以确认的摘要生成 IEP 版本，原件按授权范围加密保存；下方四项摘要框此时不再使用。</p></div>__SUMMARIES__
<div id="originalSection" hidden><p class="help">原件可选，最多 8 MiB。允许 PDF、DOCX、PNG、JPG/JPEG、TXT；不会自动提取或生成结论。</p><div class="file-control"><input id="documentFile" type="file" accept=".pdf,.docx,.png,.jpg,.jpeg,.txt"><label for="documentFile"><strong>选择资料原件</strong><span id="selectedFileName">尚未选择原件</span></label></div></div><p id="summaryModeNotice" class="help">仅摘要模式：不会读取或上传原件。</p></section>
<button class="button primary" id="saveDocument" type="submit">保存资料版本</button><button class="button quiet" id="cancelVersion" type="button" hidden>取消新版本</button></fieldset></form></div></div></section>
<section id="panelReferences" role="tabpanel" aria-labelledby="tabReferences" hidden><h2>课堂引用历史</h2><p class="help">只有视频中当前有效的已确认学生，才能在任务页选择资料版本。这里不生成学习结论或千字报告。</p><div id="referenceList" class="records"></div></section>""".replace("__SUMMARIES__", summaries).replace("__ALERT__", _ALERT_ICON)
    script = COMMON.replace("__ACCOUNT__", _account_payload(account)) + r"""
const studentId=queryId('student_id');let tabInitialized=false;
const auth=()=>workspace?.authorization,activeAuth=()=>auth()?.status==='active'&&auth().valid_until>today();
const verified=()=>teacher&&workspace?.student?.student_id===studentId&&byId('studentVerified').checked;
function controls(){const blocked=loading||writing||uncertain;byId('refreshButton').disabled=loading||writing;byId('studentVerified').disabled=blocked||!workspace||!teacher;byId('authorizationFields').disabled=blocked||!verified()||activeAuth()||workspace?.vault?.available!==true;byId('documentFields').disabled=blocked||!verified()||!activeAuth()||workspace?.vault?.available!==true;byId('documentType').disabled=!!byId('supersedesId').value;byId('documentFile').disabled=blocked||!verified()||!activeAuth()||auth()?.storage_mode!=='original_and_summary';document.querySelectorAll('[data-delete],[data-version],[data-document],[data-reference],#withdrawAuthorization').forEach(node=>node.disabled=blocked||!verified());byId('saveAuthorization').textContent=writing?'正在提交并核对…':'登记授权';byId('saveDocument').textContent=writing?'正在提交并核对…':'保存资料版本';byId('authorizationHelp').textContent=uncertain?'提交结果未确认，请先刷新记录。':!verified()?'请先在上方核对这位学生。':activeAuth()?'已有有效授权；如需改变范围，须先撤回，原资料将不可访问。':workspace?.vault?.available!==true?'加密存储不可用，暂不能登记或上传。':'请据实填写并勾选授权声明。';}
function retentionError(){const value=byId('retainUntil').value,limit=auth()?.valid_until||'';if(value&&limit&&value>limit)return '资料保存至日期不得晚于授权截止日 '+limit+'，请调整保存期限。';if(value&&value<=today())return '资料保存至日期须晚于今天。';return '';}
function documentFieldError(){if(!types[byId('documentType').value])return ['documentType','请选择资料类型。'];if(!byId('documentDate').value)return ['documentDate','请填写资料日期。'];if(byId('documentDate').value>today())return ['documentDate','资料日期不能晚于今天。'];if(!byId('retainUntil').value)return ['retainUntil','请填写资料保存至日期。'];const source=byId('sourceRef').value.trim();if(!source)return ['sourceRef','请填写资料来源。'];if(source.length>200)return ['sourceRef','资料来源最多 200 字，请精简后再提交。'];return null;}
function checkRetention(){const message=retentionError(),node=byId('retainUntilError');byId('retainUntil').setCustomValidity(message);node.textContent=message;node.hidden=!message;return !message;}
function markField(id){document.querySelectorAll('#documentForm .field.has-error').forEach(node=>node.classList.remove('has-error'));const field=id&&byId(id)?.closest('.field');if(field)field.classList.add('has-error');}
function sourceCount(){const length=byId('sourceRef').value.trim().length;byId('sourceRefCount').textContent=length?'已输入 '+length+' / 200 字':'最多 200 字';byId('sourceRefCount').classList.toggle('field-error',length>200);}
async function loadIepStatus(){const node=byId('iepStatus');node.hidden=true;node.textContent='';delete node.dataset.state;if(!workspace||!activeAuth())return;try{const data=await request('/iep-context?student_id='+encodeURIComponent(studentId));const context=data.iep_context;if(!context||context.student_id!==studentId)return;const text={available:'IEP 当前版本：'+(context.iep?('版本 '+context.iep.version+' · 资料日期 '+context.iep.document_date):'已确认')+'。分析与评分只读取 IEP 类型资料，专业评估等资料不会混入 IEP。',ambiguous:'IEP 状态：同时存在 '+(context.candidates||[]).length+' 份有效 IEP，系统不自动选择任意一份。请核实后删除多余版本，或在课堂引用中明确使用的版本。',not_found:'IEP 状态：当前没有有效 IEP。专业评估等其他资料不会作为 IEP 使用。',unavailable:'IEP 状态：'+(context.message||'资料当前不可用于分析和评分。')}[context.status];if(text){node.textContent=text;node.dataset.state=context.status;node.hidden=false;}}catch(_){node.textContent='IEP 状态暂未读取，请刷新记录核对。';node.dataset.state='unavailable';node.hidden=false;}}
const dossierIntake=window.IepIntake?IepIntake.create(byId('dossierIepIntake'),{prefix:'dossierIep',embedded:true}):null;
function syncIepIntake(){const show=byId('documentType').value==='iep'&&!!dossierIntake;byId('dossierIepIntakeWrap').hidden=!show;}
async function saveIepIntake(){const check=dossierIntake.validate();if(!check.ok){dossierIntake.showError(check.message,check.field);notice(check.message);return;}if(writing||loading||uncertain)return;const iep={...dossierIntake.payload(),supersedes_id:byId('supersedesId').value,document_date:byId('documentDate').value,retain_until:byId('retainUntil').value,source_ref:byId('sourceRef').value.trim()};const isVersion=!!iep.supersedes_id,count=(iep.items||[]).length;writing=true;clearNotice();controls();try{const result=await request('/iep-intake/commit',{student_id:studentId,iep});if(!result.iep?.document_id)throw new Error('提交结果尚未确认，请刷新记录，避免重复提交。');dirty=false;resetInputs();const ok=await load(true);if(!ok||!workspace?.documents.some(doc=>doc.document_id===result.iep.document_id&&doc.available===true))throw new Error('请求已提交，但刷新结果尚未确认这次变更。请刷新核对，暂勿重复提交。');const text=(isVersion?'IEP 新版本已保存：':'IEP 已保存：')+'系统摘要 '+count+' 条'+(iep.manual_supplement?' + 教师补充':'')+(result.iep.original_saved?'，原件已加密保存':'');notice(text+'。已重新读取服务器记录，变更已确认。','success');toast(text);flash('[data-document-card="'+CSS.escape(result.iep.document_id)+'"]');}catch(error){if([400,409].includes(error.status)&&String(error.code||'').startsWith('iep')||error.status===400){dossierIntake.showError(error.message,error.field);notice(error.message);}else{uncertain=true;workspace=null;clearContent();notice(error.message+' 当前已暂停写入，请先刷新核对。');}}finally{writing=false;controls();}}
function resetInputs(){dossierIntake?.reset();byId('authorizationForm').reset();byId('documentForm').reset();byId('retainUntilError').hidden=true;byId('retainUntil').setCustomValidity('');byId('supersedesId').value='';byId('selectedFileName').textContent='尚未选择原件';byId('documentFormTitle').textContent='新增资料';byId('cancelVersion').hidden=true;markField('');sourceCount();syncIepIntake();}
function setCounts(docs,authCount,refs){byId('countDocuments').textContent=docs;byId('countAuthorization').textContent=authCount;byId('countReferences').textContent=refs;}
function clearContent(){for(const id of ['authorizationRecord','documentList','referenceList'])byId(id).replaceChildren();byId('studentName').textContent='尚未确认学生资料';byId('studentMeta').replaceChildren();byId('studentAvatar').textContent='?';byId('studentVerified').checked=false;byId('workspaceGate').textContent='未取得可用资料，请刷新；不可据此判断没有记录。';byId('reminderCard').dataset.state='warning';setCounts('–','–','–');}
const TAB_HASH={tabDocuments:'documents',tabAuthorization:'authorization',tabReferences:'references'};
const tabNav=window.RxUI&&window.RxUI.tabHash?window.RxUI.tabHash({names:Object.values(TAB_HASH),current:()=>{const on=document.querySelector('[role=tab][aria-selected=true]');return on?TAB_HASH[on.id]||'':'';},apply:name=>{const id=Object.keys(TAB_HASH).find(key=>TAB_HASH[key]===name);if(id&&tabInitialized)switchTab(id);}}):null;
const initialTabId=(()=>{const name=tabNav&&tabNav.initial();return name?Object.keys(TAB_HASH).find(key=>TAB_HASH[key]===name)||'':'';})();
function switchTab(id,pushHistory){if(tabNav&&TAB_HASH[id]){const on=document.querySelector('[role=tab][aria-selected=true]');tabNav.set(TAB_HASH[id],!!pushHistory&&!!on&&on.id!==id);}for(const button of document.querySelectorAll('[role=tab]')){const chosen=button.id===id;button.setAttribute('aria-selected',String(chosen));button.tabIndex=chosen?0:-1;byId(button.getAttribute('aria-controls')).hidden=!chosen;}}
const tabs=[...document.querySelectorAll('[role=tab]')];tabs.forEach((button,index)=>{button.addEventListener('click',()=>switchTab(button.id,true));button.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;switchTab(tabs[next].id,true);tabs[next].focus();}});});
function documentCard(doc,docs){const usable=usableDocument(doc)&&activeAuth()&&doc.authorization_id===auth().authorization_id;const latest=!docs.some(other=>other.family_id===doc.family_id&&Number(other.version)>Number(doc.version));const [stateText,stateTone]=docState(doc,usable);return `<article class="record" data-document-card="${esc(doc.document_id)}"><div class="record-head"><div class="doc-title">${typeIcon(doc.document_type)}<div><h3>${esc(types[doc.document_type]||'资料')}</h3><span class="version-chip">版本 ${esc(doc.version)}${latest?'':' · 已有新版本'} · 编号 ${idChip(doc.document_id,'资料编号')}</span></div></div><span class="doc-badges">${badge(stateText,stateTone)}${usable?countdown(doc.retain_until):''}</span></div><p>资料日期 ${esc(doc.document_date||'未返回')} · 保存至 ${esc(doc.retain_until||'未返回')}</p>${usable?`${expiryNotice(doc)}<p>来源：${esc(doc.source_ref)}</p><details><summary>查看本版本授权摘要</summary>${doc.intake&&window.IepIntake?IepIntake.previewHtml(doc.intake):''}<dl>${Object.entries(labels).map(([key,label])=>`<div><dt>${esc(label)}</dt><dd>${esc(doc.summary?.[key]||'未录入')}</dd></div>`).join('')}</dl></details><p>${doc.has_file?'已保存原件：'+esc(doc.filename||'原件'):'仅保存摘要，未保存原件'}</p><div class="record-actions">${doc.has_file?`<button type="button" class="button" data-document="${esc(doc.document_id)}">下载原件</button>`:''}${latest?`<button type="button" class="button" data-version="${esc(doc.document_id)}">录入新版本</button>`:''}<button type="button" class="button danger" data-delete="${esc(doc.document_id)}">删除此版本</button></div>`:'<p>此版本不可访问，不展示来源、摘要或原件。保留最小历史记录；课堂引用不会改指向其他学生或版本。</p>'}</article>`;}
function render(){const student=workspace.student;byId('studentName').textContent=student.display_name||'姓名未返回';byId('studentAvatar').textContent=Array.from(String(student.display_name||'').trim())[0]||'?';byId('studentMeta').innerHTML=[student.student_code?badge('校内编号 '+student.student_code,'info'):badge('未填校内编号','neutral'),student.class_name?badge(student.class_name,'neutral'):badge('未填班级','neutral'),'<span class="meta-label">学生编号</span>'+idChip(student.student_id,'学生编号')].join('');byId('legacyNotice').textContent=workspace.legacy_notice||'旧资料库不会按姓名自动迁移。请核对正确学生与授权后重新录入。';const vaultOk=workspace.vault?.available===true;byId('workspaceGate').textContent=vaultOk?'已读取本校学生，请先在上方核对姓名、编号和班级后再登记授权或录入资料。':'加密存储暂不可用，暂停登记与上传；不会回退为明文保存。';byId('reminderCard').dataset.state=vaultOk?'ok':'warning';
  byId('authorizationRecord').innerHTML=auth()?`<article class="record"><div class="record-head"><h3>${esc(statusName(auth().status))}</h3><span class="doc-badges">${activeAuth()?badge('有效','success')+countdown(auth().valid_until):badge(statusName(auth().status),'neutral')}</span></div><dl><div><dt>授权依据</dt><dd>${esc(activeAuth()?auth().reference:'已不可用，不展示原授权内容')}</dd></div><div><dt>授权范围</dt><dd>${activeAuth()?(auth().storage_mode==='summary_only'?'仅摘要，不保存原件':'摘要及可选原件'):'历史授权'}</dd></div><div><dt>有效期至</dt><dd>${esc(auth().valid_until||'未返回')}</dd></div></dl>${activeAuth()?'<button class="button danger" id="withdrawAuthorization" type="button">撤回授权并停止访问相关资料</button>':''}</article>`:'<div class="empty-state">尚无有效授权。核对学生后，在此登记实际获准的范围和期限。</div>';
  const docs=workspace.documents;byId('documentList').innerHTML=docs.length?docs.map(doc=>documentCard(doc,docs)).join(''):'<div class="empty-state">还没有资料版本。先完成授权，再录入必要摘要；原件可选。</div>';
  setCounts(docs.length,activeAuth()?1:0,workspace.references.length);
  byId('referenceList').innerHTML=referenceRows(workspace.references);const original=activeAuth()&&auth().storage_mode==='original_and_summary';byId('originalSection').hidden=!original;byId('summaryModeNotice').hidden=original;if(!original){byId('documentFile').value='';byId('selectedFileName').textContent='尚未选择原件';}byId('documentGate').textContent=activeAuth()?'当前范围：'+(original?'摘要及可选原件':'仅摘要，不上传原件')+'；保存期限不得晚于 '+auth().valid_until+'。':'资料录入已暂停：请先核对学生并登记有效授权。';byId('retainHelp').innerHTML=(activeAuth()?'不得晚于授权截止日期 <strong>'+esc(auth().valid_until)+'</strong>；':'不得晚于授权截止日期；')+'<strong>所选日期零点起不可访问</strong>（服务器本地时间，当前内测为北京时间）。';byId('retainUntil').max=auth()?.valid_until||future(60);if(!tabInitialized){switchTab(initialTabId||(activeAuth()?'tabDocuments':'tabAuthorization'));tabInitialized=true;}controls();}
async function load(afterWrite=false){if(loading||writing&&!afterWrite)return false;loading=true;const checked=byId('studentVerified').checked;workspace=null;clearContent();controls();if(!afterWrite)clearNotice();try{if(!teacher)throw new Error('仅资料所属学校的教师可访问。公司后台不提供学生资料内容。');if(!studentId)throw new Error('请先返回本校名册，选择一位明确的学生。');const data=await request('/student?student_id='+encodeURIComponent(studentId));if(data.workspace?.student?.student_id!==studentId||!Array.isArray(data.workspace.documents)||!Array.isArray(data.workspace.references))throw new Error('接口未返回这位学生的完整工作区，请刷新。');workspace=data.workspace;uncertain=false;byId('studentVerified').checked=checked;render();loadIepStatus();return true;}catch(error){workspace=null;uncertain=true;clearContent();notice(error.message);return false;}finally{loading=false;controls();}}
byId('studentVerified').addEventListener('change',controls);
byId('authorizationUntil').min=future(1);byId('authorizationUntil').max=future(60);byId('documentDate').max=today();byId('retainUntil').min=future(1);
byId('authorizationForm').addEventListener('submit',event=>{event.preventDefault();if(byId('authorizationFields').disabled||!byId('authorizationConfirmed').checked||!byId('authorizationForm').reportValidity())return;const reference=byId('authorizationReference').value.trim();if(!reference)return notice('请填写实际授权依据。');const payload={student_id:studentId,reference,storage_mode:byId('storageMode').value,valid_until:byId('authorizationUntil').value,confirmed:true};mutate('/authorization',payload,'authorization',(response,current)=>current?.authorization?.authorization_id===response.authorization.authorization_id&&current.authorization.status==='active',{text:'授权已登记，有效期至 '+payload.valid_until,after:()=>switchTab('tabDocuments')});});
byId('documentFile').addEventListener('change',()=>{const file=byId('documentFile').files[0];byId('selectedFileName').textContent=file?file.name+' · '+(file.size/1048576).toFixed(2)+' MiB':'尚未选择原件';});
byId('documentType').addEventListener('change',syncIepIntake);
byId('retainUntil').addEventListener('input',checkRetention);byId('retainUntil').addEventListener('change',checkRetention);byId('sourceRef').addEventListener('input',sourceCount);
byId('documentForm').addEventListener('input',event=>{const field=event.target.closest('.field');if(field)field.classList.remove('has-error');});
byId('documentForm').addEventListener('submit',async event=>{event.preventDefault();if(byId('documentFields').disabled)return;if(!checkRetention()){notice(retentionError());markField('retainUntil');byId('retainUntil').focus();return;}const missing=documentFieldError();if(missing){notice(missing[1]);markField(missing[0]);byId(missing[0]).focus();return;}markField('');if(!byId('documentForm').reportValidity())return;if(byId('documentType').value==='iep'&&dossierIntake&&!dossierIntake.isEmpty()){await saveIepIntake();return;}const summary=Object.fromEntries(Object.keys(labels).map(key=>[key,byId(key).value.trim()])),original=auth().storage_mode==='original_and_summary',file=original?byId('documentFile').files[0]:null;if(!Object.values(summary).some(Boolean)&&!file){notice('至少录入一项授权摘要，或在允许原件的模式下选择文件。');byId('learning_goals').focus();return;}if(file&&(file.size<=0||file.size>8*1024*1024||! /\.(pdf|docx|png|jpg|jpeg|txt)$/i.test(file.name)))return notice('原件须为允许的格式，大小大于 0 且不超过 8 MiB。');const payload={student_id:studentId,authorization_id:auth().authorization_id,document_type:byId('documentType').value,document_date:byId('documentDate').value,source_ref:byId('sourceRef').value.trim(),retain_until:byId('retainUntil').value,summary,filename:file?file.name:'',content_base64:'',supersedes_id:byId('supersedesId').value};if(!payload.source_ref)return notice('请填写资料来源。');if(!types[payload.document_type])return notice('请选择资料类型。');if(file){writing=true;controls();try{payload.content_base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error('文件读取失败，请重新选择。'));reader.readAsDataURL(file);});}catch(error){notice(error.message);return;}finally{writing=false;controls();}}const isVersion=!!payload.supersedes_id;await mutate('/documents',payload,'document',(response,current)=>current?.documents.some(doc=>doc.document_id===response.document.document_id&&doc.available===true),{text:(isVersion?'新版本已保存：':'资料已保存：')+types[payload.document_type],after:result=>flash('[data-document-card="'+CSS.escape(result.document.document_id)+'"]')});});
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target||writing||loading||uncertain||!verified())return;
  if(target.id==='withdrawAuthorization'&&activeAuth()){const id=auth().authorization_id;confirmDanger({title:'撤回这位学生的资料授权？',message:'撤回后本校将不能再使用这位学生的授权资料。',consequences:['相关摘要和原件立即不可访问，并请求物理清理。','已有课堂引用会标记失效，相关报告会显示「已过期」。','此操作不能恢复原内容，如需继续使用须重新登记授权。'],confirmLabel:'确认撤回授权',cancelLabel:'取消'}).then(ok=>{if(!ok||writing||loading||uncertain||auth()?.authorization_id!==id)return;mutate('/authorization/withdraw',{student_id:studentId,authorization_id:id,confirmed:true},'result',(_,current)=>!current?.authorization||current.authorization.authorization_id!==id||current.authorization.status!=='active',{text:'授权已撤回，相关资料已停止访问'});});}
  const id=target.dataset.delete||target.dataset.version||target.dataset.document,doc=workspace?.documents.find(item=>item.document_id===id);if(!doc||doc.available!==true)return;
  if(target.dataset.delete)confirmDanger({title:'删除这个资料版本？',message:'将删除「'+(types[doc.document_type]||'资料')+' · 版本 '+doc.version+'」。',consequences:['原件与摘要将不可访问，并请求物理清理。','历史课堂引用不会自动替换为新版本，会标记为资料不可用。','此操作不能恢复。'],confirmLabel:'确认删除',cancelLabel:'取消'}).then(ok=>{if(!ok||writing||loading||uncertain)return;mutate('/documents/delete',{student_id:studentId,document_id:id,confirmed:true},'result',(_,current)=>!current?.documents.some(item=>item.document_id===id&&item.available===true),{text:'资料版本 '+shortId(id)+' 已删除'});});
  if(target.dataset.document)download('/document?document_id='+encodeURIComponent(id),(doc.filename||'资料原件').split(/[\\/]/).pop());
  if(target.dataset.version){if(dirty&&!window.confirm('录入新版本会清空尚未保存的表单，继续吗？'))return;byId('documentForm').reset();markField('');byId('supersedesId').value=id;byId('documentType').value=doc.document_type;syncIepIntake();byId('selectedFileName').textContent='尚未选择原件';byId('documentFormTitle').textContent='录入新版本（基于版本 '+doc.version+'）';byId('cancelVersion').hidden=false;dirty=false;controls();sourceCount();byId('documentFormTitle').scrollIntoView({block:'start',behavior:'smooth'});byId('documentDate').focus({preventScroll:true});}
});
byId('cancelVersion').addEventListener('click',()=>{if(dirty&&!window.confirm('放弃此版本未保存内容？'))return;byId('documentForm').reset();byId('supersedesId').value='';byId('documentFormTitle').textContent='新增资料';byId('cancelVersion').hidden=true;byId('selectedFileName').textContent='尚未选择原件';markField('');sourceCount();dirty=false;controls();});
load();
"""
    return _document(title="学生资料与授权", body=_shell(content, account=account, active="students"),
                     page_style=STYLE + IEP_INTAKE_CSS, script=UI_DRAFT_STORE_JS + IEP_INTAKE_JS + script)


def render_task(account: Any | None = None) -> str:
    step_bar = steps(("选择已确认学生", "选择资料版本", "确认保存"), 0, aria_label="关联学生资料步骤", element_id="referenceSteps")
    content = """<div class="page-heading"><div><span class="eyebrow">课堂证据 · 资料版本引用</span><h1>关联学生资料</h1><p class="lead" id="courseContext">正在核验课堂与当前身份依据。</p></div></div><p class="task-gate" id="taskGate" role="status">只显示本任务当前版本中已确认身份的学生。</p><div class="dossier-grid"><section><h2>本次课堂引用</h2><p class="help">先选已确认学生，再勾选 1–10 个资料版本。新版本不会修改旧引用；引用记录不是自动评估或学习结论。</p>__STEPS__
<div class="rx-empty" id="noStudentState" hidden><svg class="rx-icon rx-empty-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg><p><strong>请先到身份确认页确认画面中的学生</strong></p><p>本课视频里还没有当前有效的已确认学生。确认后回到这里刷新，即可选择学生资料版本。</p><a class="rx-btn rx-btn-primary" id="identityLink" href="/demo2/upload">去确认画面中的学生</a></div>
<form class="dossier-form" id="referenceForm"><fieldset id="referenceFields" disabled>
<div class="step-block" id="stepStudent" data-state="current"><h3><b>1</b>选择已确认学生</h3><div class="field"><label for="referenceStudent">已确认学生（必选）</label><select id="referenceStudent" required><option value="">请选择已确认学生</option></select></div><p class="selected-student" id="selectedStudentContext" role="status"></p><a class="button quiet" id="studentDossierLink" hidden>管理这位学生的资料与授权</a></div>
<div class="step-block" id="stepDocuments" data-state="todo"><h3><b>2</b>选择资料版本（1–10 个）</h3><div class="records" id="referenceDocuments"></div></div>
<div class="step-block" id="stepConfirm" data-state="todo"><h3><b>3</b>确认保存</h3><label class="check"><input id="referenceConfirmed" type="checkbox" required><span>已核对该学生的当前画面身份与资料版本，确认用于本次课堂教育支持。</span></label><button class="button primary" id="saveReference" type="submit" disabled>保存课堂引用记录</button></div>
</fieldset></form><p class="help" id="referenceHelp" role="status">尚未核实可用学生与资料。</p></section><section class="entry-pane"><h2>已留存的引用</h2><p class="help">导出时重新核验授权、资料和身份依据。已撤回、删除、过期或重处理的来源不得当作有效依据。</p><div id="referenceList" class="records"></div></section></div>""".replace("__STEPS__", step_bar)
    script = COMMON.replace("__ACCOUNT__", _account_payload(account)) + r"""
const taskId=queryId('task_id');byId('backLink').href=taskId?'/demo2/video?id='+encodeURIComponent(taskId):'/demo2/upload';byId('backLink').textContent='返回视频任务';byId('identityLink').href=taskId?'/demo2/identity?task_id='+encodeURIComponent(taskId):'/demo2/upload';
const selected=()=>workspace?.students.find(student=>student.student_id===byId('referenceStudent').value),chosen=()=>[...document.querySelectorAll('[data-doc-id]:checked')].map(node=>node.dataset.docId);
function stepState(){const count=chosen().length,student=selected(),docsOk=count>=1&&count<=10,index=!student?0:!docsOk?1:2;if(window.RxUI)RxUI.setStep('referenceSteps',index);[['stepStudent',0],['stepDocuments',1],['stepConfirm',2]].forEach(([id,step])=>{byId(id).dataset.state=step<index?'done':step===index?'current':'todo';});}
function controls(){const blocked=loading||writing||uncertain||!teacher||!workspace;byId('refreshButton').disabled=loading||writing;const noStudents=!!workspace&&!workspace.students.length;byId('noStudentState').hidden=!noStudents;byId('referenceForm').hidden=noStudents;byId('referenceFields').disabled=blocked||!workspace?.students.length;byId('saveReference').disabled=blocked||!selected()||!workspace?.task?.frame_revision||!byId('referenceConfirmed').checked||chosen().length<1||chosen().length>10;document.querySelectorAll('[data-reference],[data-withdraw-reference]').forEach(node=>node.disabled=blocked);byId('saveReference').textContent=writing?'正在提交并核对…':'保存课堂引用记录';const count=chosen().length;byId('referenceHelp').textContent=uncertain?'记录尚未确认，请先刷新。':!workspace?.students.length?'没有可引用的学生。请先返回视频任务确认当前画面身份；不会套用其他学生或旧版本。':!selected()?'请选择一位当前已确认的学生。':count<1?'请至少勾选 1 个资料版本后再保存。':count>10?'最多勾选 10 个资料版本，当前已选 '+count+' 个，请取消多余版本。':!byId('referenceConfirmed').checked?'已选 '+count+' 个版本，请勾选核对确认后保存。':'已选 '+count+' 个版本（最多 10 个），请核对身份与授权范围。';byId('referenceHelp').classList.toggle('field-error',!!selected()&&(count<1||count>10));stepState();}
function resetInputs(){byId('referenceForm').reset();}
function clearContent(){byId('courseContext').textContent='课堂与学生身份尚未核验';byId('referenceStudent').innerHTML='<option value="">请选择已确认学生</option>';byId('referenceDocuments').replaceChildren();byId('selectedStudentContext').replaceChildren();byId('referenceList').replaceChildren();byId('studentDossierLink').hidden=true;byId('taskGate').textContent='未取得当前可用证据，请刷新记录。';}
const studentLabel=student=>[student.display_name||'姓名未返回',student.student_code?'编号 '+student.student_code:'',student.class_name||'',student.confirmed_binding_count+' 条当前确认'].filter(Boolean).join(' · ');
function renderDocuments(){const student=selected();byId('selectedStudentContext').innerHTML=student?`<strong>${esc(student.display_name||'姓名未返回')}</strong>${student.student_code?badge('编号 '+student.student_code,'info'):''}<span>学生编号</span>${idChip(student.student_id,'学生编号')}<span class="rx-sr">完整学生编号 ${esc(student.student_id)}</span><span>· ${esc(student.confirmed_binding_count)} 条当前身份确认</span>`:'';byId('referenceConfirmed').checked=false;byId('studentDossierLink').hidden=!student;if(student)byId('studentDossierLink').href='/demo2/dossier?student_id='+encodeURIComponent(student.student_id);const docs=(student?.documents||[]).filter(usableDocument);byId('referenceDocuments').innerHTML=docs.length?docs.map(doc=>`<label class="record check doc-option"><input type="checkbox" data-doc-id="${esc(doc.document_id)}">${typeIcon(doc.document_type)}<span class="doc-option-body"><strong>${esc(types[doc.document_type]||'资料')} · 版本 ${esc(doc.version)}</strong><span class="doc-badges">${badge('可用','success')}${countdown(doc.retain_until)}</span><span>资料日期 ${esc(doc.document_date||'未返回')} · 保存至 ${esc(doc.retain_until||'未返回')}</span><span>${expiryNotice(doc)?'即将到期 · ':''}来源：${esc(doc.source_ref||'未返回')}</span></span></label>`).join(''):'<div class="empty-state">'+(student?'这位学生暂无可用授权资料。请先管理资料与授权，再刷新课堂记录。':'选择已确认学生后显示该学生可用的资料版本。')+'</div>';controls();}
async function load(afterWrite=false){if(loading||writing&&!afterWrite)return false;loading=true;workspace=null;clearContent();controls();if(!afterWrite)clearNotice();try{if(!teacher)throw new Error('公司管理员仅可查看运营元数据，不能读取学生课堂资料。');if(!taskId)throw new Error('请从一个明确的视频任务进入课堂资料引用。');const data=await request('/task?task_id='+encodeURIComponent(taskId));if(data.workspace?.task?.task_id!==taskId||!Array.isArray(data.workspace.students)||!Array.isArray(data.workspace.references))throw new Error('接口未返回当前课堂完整引用工作区。');workspace=data.workspace;workspace.students=workspace.students.filter(student=>student.student_id&&Number(student.confirmed_binding_count)>0);uncertain=false;byId('courseContext').textContent=[workspace.task.course_name,workspace.task.course_id,workspace.task.frame_revision?'身份版本 '+shortId(workspace.task.frame_revision):''].filter(Boolean).join(' · ');byId('courseContext').title=workspace.task.frame_revision?'完整身份版本 '+workspace.task.frame_revision:'';byId('taskGate').textContent=workspace.notice||'仅对当前有效身份与获准资料版本建立引用，不推断跨帧或跨学生关系。';byId('referenceStudent').innerHTML='<option value="">请选择已确认学生</option>'+workspace.students.map(student=>`<option value="${esc(student.student_id)}">${esc(studentLabel(student))}</option>`).join('');byId('referenceList').innerHTML=referenceRows(workspace.references,{withdraw:teacher});if(workspace.students.length===1)byId('referenceStudent').value=workspace.students[0].student_id;renderDocuments();return true;}catch(error){workspace=null;uncertain=true;clearContent();notice(error.message);return false;}finally{loading=false;controls();}}
byId('referenceStudent').addEventListener('change',renderDocuments);byId('referenceForm').addEventListener('change',controls);
byId('referenceForm').addEventListener('submit',event=>{event.preventDefault();if(byId('saveReference').disabled||!byId('referenceForm').reportValidity())return;const student=selected(),ids=chosen();if(!student||ids.some(id=>!student.documents.some(doc=>doc.document_id===id&&doc.available===true)))return notice('资料已变化，请刷新课堂工作区。');mutate('/references',{task_id:taskId,student_id:student.student_id,frame_revision:workspace.task.frame_revision,document_ids:ids,confirmed:true},'reference',(response,current)=>current?.references.some(ref=>ref.reference_id===response.reference.reference_id),{text:'课堂引用已保存（'+ids.length+' 个资料版本）',after:result=>flash('[data-reference-card="'+CSS.escape(result.reference.reference_id)+'"]')});});
document.addEventListener('click',event=>{const button=event.target.closest('[data-withdraw-reference]');if(!button||button.disabled)return;const id=button.dataset.withdrawReference;confirmDanger({title:'撤回本课的资料引用？',message:'撤回本课对该学生资料的引用授权。',consequences:['IEP 与专业资料不再进入本课分析和评分。','历史记录保留并标记失效，已生成的报告会显示「已过期」。'],confirmLabel:'确认撤回引用',cancelLabel:'取消'}).then(ok=>{if(!ok||writing||loading||uncertain)return;mutate('/references/withdraw',{reference_id:id,confirmed:true},'reference',(_,current)=>current?.references.some(ref=>ref.reference_id===id&&ref.withdrawn===true),{text:'本课引用授权已撤回'});});});
load();
"""
    return _document(title="课堂资料引用", body=_shell(content, account=account, active="upload"), page_style=STYLE, script=script)


_ADMIN_STYLE = r"""
.admin-kpi-groups{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:18px 0 8px}
.admin-kpi-groups .rx-kpi-grid{grid-template-columns:repeat(auto-fit,minmax(120px,1fr))}
.admin-kpi-groups .rx-kpi-value{color:var(--blue-deep,#214e87)}
.channel-summary{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}
.channel-summary .record h3{display:flex;justify-content:space-between;align-items:center;gap:8px}
.channel-summary .channel-facts{grid-template-columns:repeat(2,minmax(0,1fr))!important}
.channel-summary .channel-facts dd{font-variant-numeric:tabular-nums;font-weight:700;color:var(--ink,#26364a)}
.channel-summary .pill{padding:2px 8px;border-radius:4px;background:#eef2f6;color:#4d5b6d;font-size:12px;font-weight:600}
@media(max-width:1000px){.admin-kpi-groups{grid-template-columns:minmax(0,1fr)}}
"""

_ADMIN_GROUPS = (
    ("资料数量", "教师已登记的资料版本，以及被课堂任务引用的次数。", (
        ("document_count", "资料版本", "含历史版本"),
        ("available_document_count", "可用版本", "授权有效、可被课堂引用"),
        ("reference_count", "课堂引用", "资料被课堂任务引用的次数"),
    )),
    ("授权状态", "授权到期或撤回后，资料会自动变为不可访问。", (
        ("authorization_count", "授权记录", "学校提交的授权总数"),
        ("active_authorization_count", "有效授权", "仍在有效期内"),
        ("expired_document_count", "到期版本", "已到期、不可再访问"),
    )),
    ("存储与清理", "原件加密保存；删除、撤回或到期后等待物理清理。", (
        ("encrypted_file_bytes", "加密文件占用", "以 KB / MB 显示"),
        ("deletion_pending_count", "待物理清理", "已不可访问、等待删除文件"),
    )),
)


def _admin_value_id(key: str) -> str:
    return "dossierKpi_" + key


def render_admin(account: Any | None = None) -> str:
    groups = "".join(
        kpi_group(title, [kpi(label, "--", hint=hint_text, value_id=_admin_value_id(key)) for key, label, hint_text in tiles],
                  description=description)
        for title, description, tiles in _ADMIN_GROUPS
    )
    content = ("""<div class="page-heading"><div><span class="eyebrow">公司后台 · 受限元数据</span><h1>学生资料运行状态</h1><p class="lead">仅查看数量、存储占用与清理状态。不提供学生姓名、文件名、授权依据、资料摘要或原件。</p></div></div><p class="gate" id="adminPolicy" role="status">正在读取资料服务状态。</p><section class="admin-kpi-groups" id="adminTotals" aria-label="资料运营计数">"""
               + groups
               + """</section><section class="section-space"><h2>通道汇总</h2><p class="help">每个通道仅展示计数和加密文件占用，不进入个人资料。</p><div class="records channel-summary" id="adminChannels"></div></section>""")
    keys = [key for _title, _desc, tiles in _ADMIN_GROUPS for key, _label, _hint in tiles]
    empty_template = json.dumps(empty_state("__TEXT__", compact=True), ensure_ascii=False).replace("</", "<\\/")
    script = COMMON.replace("__ACCOUNT__", _account_payload(account)) + r"""
const METRIC_KEYS=__METRIC_KEYS__,EMPTY_TEMPLATE=__EMPTY__;
const BYTE_KEYS=new Set(['encrypted_file_bytes']);
const number=value=>typeof value==='number'&&Number.isFinite(value)&&value>=0?value.toLocaleString('zh-CN'):'未返回';
// Always KB or larger: raw byte counts such as 「204」 read as a mistake to operators.
const bytesText=value=>{if(typeof value!=='number'||!Number.isFinite(value)||value<0)return '未返回';if(value===0)return '0 KB';if(value<1048576)return (value/1024).toFixed(1)+' KB';if(value<1073741824)return (value/1048576).toFixed(1)+' MB';return (value/1073741824).toFixed(2)+' GB';};
const metricText=(key,value)=>BYTE_KEYS.has(key)?bytesText(value):number(value);
const CHANNEL_FACTS=[['document_count','资料版本'],['available_document_count','可用版本'],['deletion_pending_count','待物理清理'],['encrypted_file_bytes','加密文件占用']];
function controls(){byId('refreshButton').disabled=loading;byId('refreshButton').textContent=loading?'刷新中…':'刷新记录';}function resetInputs(){}
function clearContent(){METRIC_KEYS.forEach(key=>{byId('dossierKpi_'+key).textContent='--';});byId('adminChannels').replaceChildren();byId('adminPolicy').textContent='未取得后台汇总，不能据此判断记录为零。';}
function channelCard(channel){const empty=!Number(channel.document_count);return `<article class="record"><h3><span>上传通道 ${number(channel.channel_no)}</span>${empty?'<span class="pill">暂无资料</span>':''}</h3><dl class="channel-facts">${CHANNEL_FACTS.map(([key,label])=>`<div><dt>${label}</dt><dd>${metricText(key,channel[key])}</dd></div>`).join('')}</dl></article>`;}
async function load(){if(loading)return;loading=true;clearNotice();clearContent();controls();try{if(!admin)throw new Error('只有公司管理员可查看资料运营汇总。');const data=await request('/admin'),summary=data.summary;if(!summary?.totals||!Array.isArray(summary.channels)||!summary.policy)throw new Error('汇总接口未返回完整元数据。');METRIC_KEYS.forEach(key=>{byId('dossierKpi_'+key).textContent=metricText(key,summary.totals[key]);});byId('adminChannels').innerHTML=summary.channels.length?summary.channels.map(channelCard).join(''):EMPTY_TEMPLATE.replace('__TEXT__','还没有上传通道的资料记录。');byId('adminPolicy').textContent='加密存储：'+(summary.vault?.available===true?'服务可用':'暂不可用')+' · 内测保存上限 '+number(summary.policy.max_retention_days)+' 天 · '+(summary.policy.training_allowed===false?'不授予训练权限':'训练策略未确认')+' · '+(summary.policy.raw_documents_visible===false?'后台不开放原件':'原件策略未确认');}catch(error){clearContent();notice(error.message);}finally{loading=false;controls();}}load();
""".replace("__METRIC_KEYS__", json.dumps(keys)).replace("__EMPTY__", empty_template)
    return _document(title="资料运行状态", body=_shell(content, admin=True, account=account),
                     page_style=STYLE + _ADMIN_STYLE, script=script)


__all__ = ["render_student", "render_task", "render_admin"]
